package llm

import (
	"math"
	"math/rand"
	"testing"

	"strix-halo-vulkan/gguf"
	"strix-halo-vulkan/safetensors"
)

// q8Tensor builds a [k, n] Q8_0 tensor out of thin air: n rows of k values,
// each 32-element block an fp16 scale and 32 levels, exactly as the
